def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

prime_words = [word for word in sentence.split() if is_prime(len(word))]
return ' '.join(prime_words)

